function App() {
  const [todos, setTodos] = useState([
    { id: 1, text: "Learn JSX", done: true },
    { id: 2, text: "Learn state", done: false },
  ]);
  const [nextId, setNextId] = useState(3);

  const add = () => {
    setTodos([...todos, { id: nextId, text: "Task " + nextId, done: false }]);
    setNextId(nextId + 1);
  };
  const toggle = (id) =>
    setTodos(todos.map((t) => (t.id === id ? { ...t, done: !t.done } : t)));
  const remove = (id) => setTodos(todos.filter((t) => t.id !== id));

  return (
    <div>
      <button onClick={add}>Add task</button>
      <ul>
        {todos.map((t) => (
          <li key={t.id}>
            <span
              onClick={() => toggle(t.id)}
              style={{ textDecoration: t.done ? "line-through" : "none", cursor: "pointer" }}
            >
              {t.text}
            </span>{" "}
            <button onClick={() => remove(t.id)}>x</button>
          </li>
        ))}
      </ul>
    </div>
  );
}

function App() {
  const [form, setForm] = useState({ name: "", email: "", newsletter: false, role: "student" });
  const [submitted, setSubmitted] = useState(null);

  function handleChange(e) {
    const { name, value, type, checked } = e.target;
    setForm({ ...form, [name]: type === "checkbox" ? checked : value });
  }
  function handleSubmit(e) {
    e.preventDefault();
    setSubmitted(form);
  }
  return (
    <form onSubmit={handleSubmit}>
      <input name="name" value={form.name} onChange={handleChange} placeholder="Name" />
      <input name="email" value={form.email} onChange={handleChange} placeholder="Email" />
      <select name="role" value={form.role} onChange={handleChange}>
        <option value="student">Student</option>
        <option value="developer">Developer</option>
      </select>
      <label>
        <input type="checkbox" name="newsletter" checked={form.newsletter} onChange={handleChange} /> Newsletter
      </label>
      <button type="submit">Submit</button>
      {submitted && <pre>{JSON.stringify(submitted, null, 2)}</pre>}
    </form>
  );
}

function Celsius({ value, onChange }) {
  return <label>Celsius: <input type="number" value={value} onChange={(e) => onChange(e.target.value)} /></label>;
}
function Fahrenheit({ value, onChange }) {
  return <label>Fahrenheit: <input type="number" value={value} onChange={(e) => onChange(e.target.value)} /></label>;
}

function App() {
  const [celsius, setCelsius] = useState("0");
  const fahrenheit = celsius === "" ? "" : String(Math.round((Number(celsius) * 9) / 5 + 32));

  function fromF(f) {
    setCelsius(f === "" ? "" : String(Math.round(((Number(f) - 32) * 5) / 9)));
  }
  return (
    <div style={{ fontFamily: "sans-serif", padding: 12, display: "grid", gap: 8 }}>
      <Celsius value={celsius} onChange={setCelsius} />
      <Fahrenheit value={fahrenheit} onChange={fromF} />
    </div>
  );
}

function App() {
  const [items, setItems] = useState([
    { id: 1, name: "Pen", price: 10, qty: 2 },
    { id: 2, name: "Book", price: 150, qty: 1 },
  ]);
  const total = items.reduce((sum, i) => sum + i.price * i.qty, 0);
  const count = items.reduce((sum, i) => sum + i.qty, 0);

  const change = (id, d) =>
    setItems(items.map((i) => (i.id === id ? { ...i, qty: Math.max(0, i.qty + d) } : i)));

  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      {items.map((i) => (
        <p key={i.id}>
          {i.name} x {i.qty}{" "}
          <button onClick={() => change(i.id, -1)}>-</button>
          <button onClick={() => change(i.id, 1)}>+</button>
        </p>
      ))}
      <hr />
      <b>{count} items, total Rs. {total}</b>
    </div>
  );
}

function App() {
  const [count, setCount] = useState(0);
  const [name, setName] = useState("");

  useEffect(() => {
    document.title = "Clicked " + count + " times";
    console.log("title effect ran, count =", count);
  }, [count]);

  useEffect(() => {
    console.log("mounted once");
  }, []);

  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      <button onClick={() => setCount(count + 1)}>Clicked {count}</button>
      <br /><br />
      <input value={name} onChange={(e) => setName(e.target.value)} placeholder="typing does not re-run the title effect" />
    </div>
  );
}

function Clock() {
  const [seconds, setSeconds] = useState(0);
  useEffect(() => {
    const id = setInterval(() => setSeconds((s) => s + 1), 1000);
    return () => clearInterval(id);
  }, []);
  return <p>Seconds: {seconds}</p>;
}

function Resize() {
  const [w, setW] = useState(window.innerWidth);
  useEffect(() => {
    const onResize = () => setW(window.innerWidth);
    window.addEventListener("resize", onResize);
    return () => window.removeEventListener("resize", onResize);
  }, []);
  return <p>Window width: {w}px</p>;
}

function App() {
  const [show, setShow] = useState(true);
  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      <button onClick={() => setShow(!show)}>{show ? "Unmount" : "Mount"} clock</button>
      {show && <Clock />}
      <Resize />
    </div>
  );
}

topics.description:
Fetching data on the client is a classic effect: sync the component with a server. A safe pattern keeps three pieces of state (data, loading, error) and cleans up when the request is no longer wanted.

### The race condition

If `userId` changes from 1 to 2 quickly, request 1 may finish **after** request 2 and overwrite the screen with outdated data. Fix with an `ignore` flag in the cleanup:

```jsx
useEffect(() => {
  let ignore = false;
  setLoading(true);
  fetchUser(userId).then(u => { if (!ignore) { setUser(u); setLoading(false); } });
  return () => { ignore = true; };
}, [userId]);
```

With real `fetch`, prefer `AbortController`: `controller.abort()` in cleanup cancels the request, and you ignore `AbortError`.

### Checklist

- Handle **loading**, **error** and **empty** states.
- Put `userId` (anything used inside) in the dependency array.
- Cleanup stale requests.
- Do not make the effect callback `async` - it must return a cleanup function or nothing; define an async function inside instead.

### Better tools

Hand-written fetch effects miss caching, retries, deduplication and refetching. For real apps use **TanStack Query**, SWR, or framework data loaders. Keep the manual version for learning and tiny cases.

